const err = $json.error || {};
// The exact shape of the error object can vary by n8n version - verify during testing.
const statusCode = Number(
  err.httpCode || err.statusCode || err.status ||
  (err.cause && (err.cause.httpCode || err.cause.statusCode)) || 0
);
const headers = err.headers || (err.cause && err.cause.headers) || {};
const retryAfterHeader = headers['retry-after'] || headers['Retry-After'];
const attempt = ($json.dm_attempt || 0) + 1;
const maxAttempts = 3;
const permanent = [400, 401, 403].includes(statusCode);
const transient = [429, 500, 502, 503, 504].includes(statusCode);
const canRetry = !permanent && transient && attempt < maxAttempts;
const waitSeconds = retryAfterHeader ? Number(retryAfterHeader) : Math.pow(2, attempt);
return {
  json: {
    ...$json,
    dm_attempt: attempt,
    dm_status_code: statusCode || null,
    dm_error_message: (err.message || JSON.stringify(err)).toString().slice(0, 500),
    dm_can_retry: canRetry,
    dm_wait_seconds: waitSeconds,
  },
};

